@Composable
fun ExpandedAppShell(
    navigator: AppNavigator,
    availableWidth: Dp,
    modifier: Modifier = Modifier,
) {
    PlatformBackHandler(enabled = navigator.canGoBack || navigator.selectedPostId != null) {
        val selectedUserId = navigator.selectedUserId
        if (navigator.selectedPostId != null && selectedUserId != null) {
            navigator.selectUser(selectedUserId)
        } else {
            navigator.goBack()
        }
    }

    AppScaffold(modifier = modifier) {
        Row(Modifier.fillMaxSize()) {
            Surface(
                modifier = Modifier
                    .width(masterPaneWidthFor(availableWidth))
                    .fillMaxHeight(),
                color = MaterialTheme.colorScheme.surface,
                border = BorderStroke(1.dp, MaterialTheme.colorScheme.outlineVariant),
            ) {
                Column(Modifier.fillMaxSize()) {
                    AppTopBar(
                        title = "Users",
                        subtitle = "24",
                        onRefresh = {},
                    )
                    UserListPlaceholder(
                        selectedUserId = navigator.selectedUserId,
                        onUserClick = navigator::selectUser,
                        compactRows = availableWidth < 840.dp,
                        modifier = Modifier.fillMaxSize(),
                    )
                }
            }
            Box(Modifier.weight(1f).fillMaxHeight()) {
                val selectedUserId = navigator.selectedUserId
                val selectedPostId = navigator.selectedPostId
                val route = navigator.currentRoute
                when {
                    selectedUserId == null -> NoSelectionPlaceholder(Modifier.fillMaxSize())
                    route is AppRoute.UserPosts -> Column(Modifier.fillMaxSize()) {
                        AppTopBar(title = "Posts", showBack = true, onBack = { navigator.goBack() })
                        PostsListPlaceholder(
                            userId = route.userId,
                            onPostClick = { _, postId -> navigator.selectPost(postId) },
                            modifier = Modifier.fillMaxSize(),
                        )
                    }
                    route is AppRoute.UserTodos -> Column(Modifier.fillMaxSize()) {
                        AppTopBar(title = "Todos", showBack = true, onBack = { navigator.goBack() })
                        TodosListPlaceholder(modifier = Modifier.fillMaxSize())
                    }
                    selectedPostId != null -> Column(Modifier.fillMaxSize()) {
                        AppTopBar(
                            title = "Post",
                            showBack = true,
                            onBack = { navigator.selectUser(selectedUserId) },
                        )
                        PostDetailPlaceholder(postId = selectedPostId, modifier = Modifier.fillMaxSize())
                    }
                    else -> UserDetailPlaceholder(
                        userId = selectedUserId,
                        onPostsClick = { navigator.navigate(AppRoute.UserPosts(it)) },
                        onTodosClick = { navigator.navigate(AppRoute.UserTodos(it)) },
                        onPostClick = { _, postId -> navigator.selectPost(postId) },
                        modifier = Modifier.fillMaxSize(),
                    )
                }
            }
        }
    }
}

package com.sliide.useractivity.ui.navigation

import androidx.compose.runtime.mutableStateListOf
import androidx.compose.runtime.mutableStateOf

class AppNavigator(initialRoute: AppRoute = AppRoute.Users) {
    private val routeStack = mutableStateListOf(initialRoute)
    private val selectedUserIdState = mutableStateOf<Long?>(null)
    private val selectedPostIdState = mutableStateOf<Long?>(null)

    val currentRoute: AppRoute
        get() = routeStack.last()

    val canGoBack: Boolean
        get() = routeStack.size > 1

    val selectedUserId: Long?
        get() = selectedUserIdState.value

    val selectedPostId: Long?
        get() = selectedPostIdState.value

    fun navigate(route: AppRoute) {
        routeStack += route
        updateSelection(route)
    }

    fun goBack(): Boolean {
        if (!canGoBack) return false
        routeStack.removeAt(routeStack.lastIndex)
        updateSelection(currentRoute)
        return true
    }

    fun resetToUsers() {
        routeStack.clear()
        routeStack += AppRoute.Users
        selectedUserIdState.value = null
        selectedPostIdState.value = null
    }

    fun selectUser(userId: Long) {
        selectedUserIdState.value = userId
        selectedPostIdState.value = null
    }

    fun selectPost(postId: Long) {
        selectedPostIdState.value = postId
    }

    private fun updateSelection(route: AppRoute) {
        when (route) {
            AppRoute.Users -> Unit
            is AppRoute.UserDetail -> selectUser(route.userId)
            is AppRoute.UserPosts -> selectUser(route.userId)
            is AppRoute.UserTodos -> selectUser(route.userId)
            is AppRoute.PostDetail -> {
                route.userId?.let(::selectUser)
                selectPost(route.postId)
            }
        }
    }
}

