package com.sliide.useractivity.presentation.users

import com.sliide.useractivity.domain.AppResult
import com.sliide.useractivity.domain.repository.UserRepository
import com.sliide.useractivity.ui.components.UserFilter
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.cancel
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.update
import kotlinx.coroutines.launch

class UserListViewModel(
    private val userRepository: UserRepository,
    private val scope: CoroutineScope = CoroutineScope(SupervisorJob() + Dispatchers.Default),
) {
    private val _state = MutableStateFlow(UserListState(isLoading = true))
    val state: StateFlow<UserListState> = _state.asStateFlow()

    init {
        loadInitial()
    }

    fun loadInitial() {
        if (_state.value.users.isNotEmpty()) return
        loadPage(page = 1, refresh = false)
    }

    fun refresh() {
        loadPage(page = 1, refresh = true)
    }

    fun retry() {
        loadPage(page = 1, refresh = false)
    }

    fun loadMore() {
        val current = _state.value
        if (current.isLoading || current.isRefreshing || current.isLoadingMore || !current.hasNextPage) return
        loadPage(page = current.page + 1, append = true)
    }

    fun setFilter(filter: UserFilter) {
        _state.update { it.copy(filter = filter, errorMessage = null) }
    }

    fun clear() {
        scope.cancel()
    }

    private fun loadPage(
        page: Int,
        refresh: Boolean = false,
        append: Boolean = false,
    ) {
        scope.launch {
            _state.update { current ->
                when {
                    append -> current.copy(isLoadingMore = true, errorMessage = null)
                    refresh && current.users.isNotEmpty() -> current.copy(isRefreshing = true, errorMessage = null)
                    else -> current.copy(isLoading = true, isRefreshing = false, errorMessage = null)
                }
            }

            when (val result = userRepository.getUsers(page = page, perPage = PageSize)) {
                is AppResult.Success -> _state.update { current ->
                    val users = if (append) current.users + result.value.items else result.value.items
                    current.copy(
                        isLoading = false,
                        isRefreshing = false,
                        isLoadingMore = false,
                        users = users,
                        page = result.value.page,
                        hasNextPage = result.value.hasNextPage,
                        errorMessage = null,
                    )
                }

                is AppResult.Failure -> _state.update { current ->
                    current.copy(
                        isLoading = false,
                        isRefreshing = false,
                        isLoadingMore = false,
                        errorMessage = result.error.toUserMessage(),
                    )
                }
            }
        }
    }

    private companion object {
        const val PageSize = 20
    }
}

package com.sliide.useractivity.presentation.users

import com.sliide.useractivity.domain.AppResult
import com.sliide.useractivity.domain.repository.UserRepository
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.cancel
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.update
import kotlinx.coroutines.launch

class UserDetailViewModel(
    private val userId: Long,
    private val userRepository: UserRepository,
    private val scope: CoroutineScope = CoroutineScope(SupervisorJob() + Dispatchers.Default),
) {
    private val _state = MutableStateFlow(UserDetailState(isLoading = true))
    val state: StateFlow<UserDetailState> = _state.asStateFlow()

    init {
        load()
    }

    fun load() {
        loadUser(refresh = false)
    }

    fun refresh() {
        loadUser(refresh = true)
    }

    fun retry() {
        loadUser(refresh = false)
    }

    fun clear() {
        scope.cancel()
    }

    private fun loadUser(refresh: Boolean) {
        scope.launch {
            _state.update { current ->
                if (refresh && current.user != null) {
                    current.copy(isRefreshing = true, errorMessage = null)
                } else {
                    current.copy(isLoading = true, isRefreshing = false, errorMessage = null)
                }
            }

            when (val result = userRepository.getUser(userId)) {
                is AppResult.Success -> _state.update { current ->
                    current.copy(
                        isLoading = false,
                        isRefreshing = false,
                        user = result.value,
                        errorMessage = null,
                    )
                }

                is AppResult.Failure -> _state.update { current ->
                    current.copy(
                        isLoading = false,
                        isRefreshing = false,
                        errorMessage = result.error.toUserMessage(),
                    )
                }
            }
        }
    }
}

package com.sliide.useractivity.ui.users

import com.sliide.useractivity.domain.model.User
import com.sliide.useractivity.domain.model.UserGender
import com.sliide.useractivity.domain.model.UserStatus

fun User.initials(): String {
    val parts = name.trim().split(Regex("\\s+")).filter(String::isNotBlank)
    return parts.take(2).mapNotNull { it.firstOrNull()?.uppercaseChar() }.joinToString("").ifBlank { "?" }
}

fun User.displayGender(): String = when (gender) {
    UserGender.Male -> "Male"
    UserGender.Female -> "Female"
    UserGender.Unknown -> "Unknown"
}

fun User.displayStatus(): String = when (status) {
    UserStatus.Active -> "Active"
    UserStatus.Inactive -> "Inactive"
    UserStatus.Unknown -> "Unknown"
}

fun User.isActive(): Boolean = status == UserStatus.Active

