import com.sliide.useractivity.presentation.users.UserListState
import com.sliide.useractivity.ui.components.ContentState
import com.sliide.useractivity.ui.components.ContentStateContainer
import com.sliide.useractivity.ui.components.SegmentedFilter
import com.sliide.useractivity.ui.components.SkeletonRow
import com.sliide.useractivity.ui.components.UserFilter
import com.sliide.useractivity.ui.shell.appBodyPaddingValues

@Composable
fun UserListScreen(
    state: UserListState,
    selectedUserId: Long?,
    onFilterSelected: (UserFilter) -> Unit,
    onUserClick: (Long) -> Unit,
    onRefresh: () -> Unit,
    onRetry: () -> Unit,
    onLoadMore: () -> Unit,
    modifier: Modifier = Modifier,
    compactRows: Boolean = false,
) {
    Column(
        modifier = modifier
            .fillMaxSize()
            .padding(appBodyPaddingValues()),
        verticalArrangement = Arrangement.spacedBy(10.dp),
    ) {
        if (!state.isInitialError) {
            SegmentedFilter(selected = state.filter, onSelected = onFilterSelected)
        }

        when {
            state.isInitialLoading -> repeat(6) { SkeletonRow() }
            state.isInitialError -> ContentStateContainer(
                modifier = Modifier.weight(1f),
                state = ContentState.Error(state.errorMessage),
                errorTitle = "Couldn’t load users",
                onRetry = onRetry,
            ) {}
            state.users.isEmpty() -> ContentStateContainer(
                modifier = Modifier.weight(1f),
                state = ContentState.Empty,
                emptyTitle = "No users found",
                emptyBody = "Try refreshing to fetch users again.",
                emptyActionLabel = "Refresh",
                onEmptyAction = onRefresh,
            ) {}
            state.filteredUsers.isEmpty() -> ContentStateContainer(
                modifier = Modifier.weight(1f),
                state = ContentState.Empty,
                emptyTitle = "No ${state.filter.label.lowercase()} users",
                emptyBody = "Nobody matches this filter right now. Try “All” to see everyone.",
                emptyActionLabel = "Show all users",
                onEmptyAction = { onFilterSelected(UserFilter.All) },
            ) {}
            else -> {
                if (state.isRefreshing) {
                    Text(
                        text = "Refreshing users…",
                        color = MaterialTheme.colorScheme.onSurfaceVariant,
                        style = MaterialTheme.typography.labelMedium,
                    )
                } else if (state.errorMessage != null) {
                    Text(
                        text = state.errorMessage,
                        color = MaterialTheme.colorScheme.error,
                        style = MaterialTheme.typography.labelMedium,
                    )
                }

                state.filteredUsers.forEach { user ->
                    UserRow(
                        user = user,
                        selected = user.id == selectedUserId,
                        compact = compactRows,
                        onClick = { onUserClick(user.id) },
                    )
                }

                LoadMoreRow(
                    isLoadingMore = state.isLoadingMore,
                    hasNextPage = state.hasNextPage,
                    onLoadMore = onLoadMore,
                )
            }
        }
    }
}

@Composable
private fun LoadMoreRow(
    isLoadingMore: Boolean,
    hasNextPage: Boolean,
    onLoadMore: () -> Unit,
) {
    when {
        isLoadingMore -> SkeletonRow()
        hasNextPage -> Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.Center) {
            OutlinedButton(onClick = onLoadMore) { Text("Load more") }
        }
        else -> Text(
            modifier = Modifier.fillMaxWidth(),
            text = "End of users",
            color = MaterialTheme.colorScheme.onSurfaceVariant,
            fontWeight = FontWeight.Medium,
            style = MaterialTheme.typography.labelSmall,
        )
    }
}

