@Composable
fun UserDetailScreen(
    state: UserDetailState,
    onRefresh: () -> Unit,
    onRetry: () -> Unit,
    modifier: Modifier = Modifier,
    onPostsClick: (() -> Unit)? = null,
    onTodosClick: (() -> Unit)? = null,
) {
    when {
        state.isInitialLoading -> UserDetailSkeleton(modifier)
        state.isInitialError -> ContentStateContainer(
            modifier = modifier.fillMaxSize(),
            state = ContentState.Error(state.errorMessage),
            errorTitle = "Couldn’t load user",
            onRetry = onRetry,
        ) {}
        state.user == null -> ContentStateContainer(
            modifier = modifier.fillMaxSize(),
            state = ContentState.Empty,
            emptyTitle = "Select a user",
            emptyBody = "Choose a user from the list to preview their profile here.",
        ) {}
        else -> UserDetailContent(
            user = state.user,
            isRefreshing = state.isRefreshing,
            errorMessage = state.errorMessage,
            onRefresh = onRefresh,
            onPostsClick = onPostsClick,
            onTodosClick = onTodosClick,
            modifier = modifier,
        )
    }
}

@Composable
private fun UserDetailContent(
    user: User,
    isRefreshing: Boolean,
    errorMessage: String?,
    onRefresh: () -> Unit,
    onPostsClick: (() -> Unit)?,
    onTodosClick: (() -> Unit)?,
    modifier: Modifier = Modifier,
) {
    Column(
        modifier = modifier
            .fillMaxSize()
            .verticalScroll(rememberScrollState())
            .padding(appBodyPaddingValues()),
        verticalArrangement = Arrangement.spacedBy(12.dp),
    ) {
        ProfileHeader(user)
        if (isRefreshing) {
            Text(
                text = "Refreshing profile…",
                color = MaterialTheme.colorScheme.onSurfaceVariant,
                style = MaterialTheme.typography.labelMedium,
            )
        } else if (errorMessage != null) {
            Text(
                text = errorMessage,
                color = MaterialTheme.colorScheme.error,
                style = MaterialTheme.typography.labelMedium,
            )
        }

        DeferredActivitySection(
            title = "Posts",
            body = "Posts arrive in the activity roadmap item.",
            onClick = onPostsClick,
        )
        DeferredActivitySection(
            title = "Todos",
            body = "Todos arrive in the activity roadmap item.",
            onClick = onTodosClick,
        )
        Surface(
            shape = RoundedCornerShape(999.dp),
            border = BorderStroke(1.dp, MaterialTheme.colorScheme.outlineVariant),
            color = MaterialTheme.colorScheme.surface,
            modifier = Modifier.clickable(onClick = onRefresh),
        ) {
            Text(
                modifier = Modifier.padding(horizontal = 16.dp, vertical = 9.dp),
                text = "Refresh profile",
                color = MaterialTheme.colorScheme.onSurface,
                fontWeight = FontWeight.SemiBold,
                style = MaterialTheme.typography.labelMedium,
            )
        }
    }
}

@Composable
private fun ProfileHeader(user: User) {
    Row(
        modifier = Modifier.fillMaxWidth(),
        horizontalArrangement = Arrangement.spacedBy(12.dp),
        verticalAlignment = Alignment.CenterVertically,
    ) {
        InitialsAvatar(user.initials(), size = 52.dp)
        Column(Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(4.dp)) {
            Text(user.name, fontWeight = FontWeight.SemiBold, style = MaterialTheme.typography.titleMedium)
            Text(user.email, color = MaterialTheme.colorScheme.onSurfaceVariant, style = MaterialTheme.typography.bodySmall)
            Row(
                modifier = Modifier.padding(top = 4.dp),
                horizontalArrangement = Arrangement.spacedBy(7.dp),
            ) {
                StatusChip(label = user.displayStatus(), active = user.isActive())
                StatusChip(label = user.displayGender())
            }
        }
    }
}

@Composable
private fun DeferredActivitySection(
    title: String,
    body: String,
    onClick: (() -> Unit)?,
) {
    Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
        SectionHeader(title = title, onClick = onClick)
        Surface(
