package com.sliide.useractivity.ui.shell

import androidx.compose.foundation.layout.fillMaxSize
import androidx.compose.runtime.Composable
import androidx.compose.runtime.DisposableEffect
import androidx.compose.runtime.collectAsState
import androidx.compose.runtime.getValue
import androidx.compose.runtime.remember
import androidx.compose.ui.Modifier
import com.sliide.useractivity.domain.repository.UserRepository
import com.sliide.useractivity.presentation.users.UserDetailViewModel
import com.sliide.useractivity.presentation.users.UserListViewModel
import com.sliide.useractivity.ui.components.AppTopBar
import com.sliide.useractivity.ui.navigation.AppNavigator
import com.sliide.useractivity.ui.navigation.AppRoute
import com.sliide.useractivity.ui.navigation.title
import com.sliide.useractivity.ui.users.UserDetailScreen
import com.sliide.useractivity.ui.users.UserListScreen

@Composable
fun CompactAppShell(
    navigator: AppNavigator,
    userRepository: UserRepository,
    modifier: Modifier = Modifier,
) {
    val route = navigator.currentRoute
    val userListViewModel = remember(userRepository) { UserListViewModel(userRepository) }
    val userListState by userListViewModel.state.collectAsState()

    DisposableEffect(userListViewModel) {
        onDispose { userListViewModel.clear() }
    }
    PlatformBackHandler(enabled = navigator.canGoBack) {
        navigator.goBack()
    }
    AppScaffold(
        modifier = modifier,
        topBar = {
            AppTopBar(
                title = route.title,
                subtitle = if (route == AppRoute.Users) userListState.users.size.toString() else null,
                showBack = navigator.canGoBack,
                onBack = if (navigator.canGoBack) ({ navigator.goBack() }) else null,
                onRefresh = if (route == AppRoute.Users) userListViewModel::refresh else null,
            )
        },
    ) {
        when (route) {
            AppRoute.Users -> UserListScreen(
                state = userListState,
                selectedUserId = navigator.selectedUserId,
                onFilterSelected = userListViewModel::setFilter,
                onUserClick = { userId -> navigator.navigate(AppRoute.UserDetail(userId)) },
                onRefresh = userListViewModel::refresh,
                onRetry = userListViewModel::retry,
                onLoadMore = userListViewModel::loadMore,
                modifier = Modifier.fillMaxSize(),
            )

            is AppRoute.UserDetail -> UserDetailRoute(
                userId = route.userId,
                userRepository = userRepository,
                onPostsClick = { userId -> navigator.navigate(AppRoute.UserPosts(userId)) },
                onTodosClick = { userId -> navigator.navigate(AppRoute.UserTodos(userId)) },
                modifier = Modifier.fillMaxSize(),
            )

            is AppRoute.UserPosts -> PostsListPlaceholder(
                userId = route.userId,
                onPostClick = { userId, postId -> navigator.navigate(AppRoute.PostDetail(userId = userId, postId = postId)) },
                modifier = Modifier.fillMaxSize(),
            )

            is AppRoute.UserTodos -> TodosListPlaceholder(modifier = Modifier.fillMaxSize())

            is AppRoute.PostDetail -> PostDetailPlaceholder(
                postId = route.postId,
                modifier = Modifier.fillMaxSize(),
            )
        }
    }
}

@Composable
internal fun UserDetailRoute(
    userId: Long,
    userRepository: UserRepository,
    modifier: Modifier = Modifier,
    onPostsClick: ((Long) -> Unit)? = null,
    onTodosClick: ((Long) -> Unit)? = null,
) {
    val viewModel = remember(userId, userRepository) { UserDetailViewModel(userId, userRepository) }
    val state by viewModel.state.collectAsState()

    DisposableEffect(viewModel) {
        onDispose { viewModel.clear() }
    }

    UserDetailScreen(
        state = state,
        onRefresh = viewModel::refresh,
        onRetry = viewModel::retry,
        onPostsClick = onPostsClick?.let { callback -> { callback(userId) } },
        onTodosClick = onTodosClick?.let { callback -> { callback(userId) } },
        modifier = modifier,
    )
}

